-- ============================================================
-- SES — DEV-ONLY seed: APP_POSITION_VIEW snapshot
-- Run LAST, after 04_seed.sql. See README.md for full run order.
--
-- WARNING: This script is for LOCAL DEVELOPMENT ONLY.
-- In production, APP_POSITION_VIEW is a VIEW owned by another
-- schema/app and is READ-ONLY for SES. The approval module never
-- writes to it.
--
-- This dev script CREATES a local snapshot TABLE named
-- APP_POSITION_VIEW (matching the production view's shape) so the
-- dynamic (REQUESTOR_MANAGER) resolution and position assignees can
-- be exercised locally. Contract Number autofill has its own dev
-- seed — see 24_contract_v_dev_seed.sql.
--
-- NEVER run this against a schema where APP_POSITION_VIEW is a real
-- view or where other apps depend on it — the CREATE would fail on
-- an existing object, and the DELETE below would mutate a shared
-- table.
-- ============================================================

SET DEFINE OFF;

-- ---- Create the dev snapshot table (idempotent-ish: errors out if
-- ---- the object already exists as something else) ----
CREATE TABLE app_position_view (
    pos_id            VARCHAR2(10) NOT NULL,
    pos_title         VARCHAR2(100),
    superior_id       VARCHAR2(10),
    empl_id           VARCHAR2(10),
    empl_name         VARCHAR2(100),
    dept_id           VARCHAR2(10),
    section_id        VARCHAR2(10),
    dept_desc         VARCHAR2(100),
    section_desc      VARCHAR2(100),
    empl_email        VARCHAR2(100),
    pjs_empl_id       VARCHAR2(10),
    pjs_empl_name     VARCHAR2(100),
    pjs_email         VARCHAR2(100),
    start_date        DATE,
    end_date          DATE,
    holder_empl_id    VARCHAR2(10),
    holder_empl_name  VARCHAR2(100),
    holder_email      VARCHAR2(100)
    -- POS_ID alone is NOT unique: several people can be assigned to the
    -- same position at once (co-officers), each as their own row. The
    -- key is POS_ID+EMPL_ID (matches AppPositionView's @IdClass).
--    CONSTRAINT pk_app_position_view PRIMARY KEY (pos_id, empl_id)
);

-- Layout seeded here (POS_ID -> TITLE -> SUPERIOR):
--   TOP000  PRESIDENT DIRECTOR & CEO                (no superior)
--   SRM000  SENIOR MANAGER, SECURITY  -> TOP000
--   MGR001  MANAGER, SECURITY        -> SRM000
--   OFF001  SECURITY OFFICER          -> MGR001
--   MGR002  MANAGER, OPERATIONS       -> SRM000
--   OPR001  DCS PANEL OPERATOR        -> MGR002
--   EXT000  EXTERNAL CONTRACTOR       -> SRM000 (no empl holder - external)
--
-- OFF001 has THREE rows (100004, 100008, 100009) to exercise position
-- targeting with multiple co-officers under the same POS_ID — approval
-- resolves ALL of them as equal approvers, no differentiation.
--
-- holder_empl_id = PJS if PJS active (start<=today<=end), else empl.
-- App users matching these empl ids must exist in APP_USER for
-- login (see platform 02_seed_data.sql admin/sysadm, plus any
-- additional LOCAL users you create).
-- ============================================================

SET DEFINE OFF;

-- Contract Number autofill now reads CONTRACT_V, not SES_CONTRACT (removed)
-- — see 24_contract_v_dev_seed.sql for the local dev snapshot.

COMMIT;
